#!/usr/bin/env node
// Language-pack tool. language-packs/*.json is the single source of truth for
// the board vocabulary; this script validates it and generates:
//   firmware/board/lib/vaani_core/src/vocab.h   (compiled into the firmware)
//   studio/lib/packs.generated.json             (imported by Studio)
//
// Usage:
//   node tools/vocab.mjs gen               validate and (re)write both files
//   node tools/vocab.mjs check             fail if the generated files are stale (CI)
//   node tools/vocab.mjs report            coverage and review status per language
//   node tools/vocab.mjs validate f.json…  validate extra pack files against keys.json
//
// No dependencies beyond Node 20+.

import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { keywordMap, validateKeyset, validatePack } from '../studio/lib/packs.js';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const PACK_DIR = join(root, 'language-packs');
const OUT_H = join(root, 'firmware/board/lib/vaani_core/src/vocab.h');
const OUT_JSON = join(root, 'studio/lib/packs.generated.json');

const readJson = (p) => JSON.parse(readFileSync(p, 'utf8'));

function load() {
  const keyset = readJson(join(PACK_DIR, 'keys.json'));
  const ks = validateKeyset(keyset);
  if (ks.errors.length) fail('keys.json', ks.errors);
  const packs = keyset.languages.map((code) => {
    const file = join(PACK_DIR, `${code}.json`);
    if (!existsSync(file)) fail('keys.json', [`language "${code}" is listed but language-packs/${code}.json is missing`]);
    const pack = readJson(file);
    const r = validatePack(pack, keyset);
    if (pack.code !== code) r.errors.push(`code is "${pack.code}" but the file is ${code}.json`);
    if (r.errors.length) fail(`${code}.json`, r.errors);
    return { pack, report: r };
  });
  const km = keywordMap(packs.map((p) => p.pack), keyset);
  if (km.errors.length) fail('keywords', km.errors);
  return { keyset, packs, keywords: km.map };
}

function fail(where, errors) {
  console.error(`✗ ${where}`);
  for (const e of errors) console.error(`  - ${e}`);
  process.exit(1);
}

const cstr = (s) => JSON.stringify(s); // ASCII-only by validation, so JSON escaping is valid C

function renderHeader({ keyset, packs, keywords }) {
  const langs = keyset.languages;
  const core = keyset.keys.filter((k) => k.core).length;
  const words = keyset.keys.map((k) => {
    const labels = packs.map(({ pack }) => {
      const e = pack.keys.find((x) => x.id === k.id);
      return cstr(e?.transliteration || k.meaning.toUpperCase());
    });
    return `    {{${labels.join(', ')}}, ${cstr(k.meaning)}, ${k.urgent}},`;
  });
  const kw = [...keywords].map(([w, id]) => `    {${cstr(w)}, ${keyset.keys.findIndex((k) => k.id === id)}},`);
  return `// GENERATED by tools/vocab.mjs from language-packs/*.json. Do not edit by hand:
// change the JSON, then run \`node tools/vocab.mjs gen\`.
#pragma once
#include <stddef.h>
#include <stdint.h>

// Language order is the caregiver-mode cycle order (keys.json "languages").
constexpr uint8_t NUM_LANGS = ${langs.length};
constexpr const char* LANG_CODES[NUM_LANGS] = {${langs.map(cstr).join(', ')}};

// Labels are transliterated because the 16x2 LCD cannot show Devanagari,
// Tamil or Bengali script. Order follows LANG_CODES.
struct Word {
  const char* label[NUM_LANGS];
  const char* en;
  bool urgent;  // urgent words beep three times when no voice file is loaded
};

// Keys 0-${core - 1} are the core row: never highlighted, dimmed or remapped, so the
// child can always refuse a suggestion or ask for help.
constexpr uint8_t CORE_KEYS = ${core};
constexpr uint8_t VOCAB_KEYS = ${keyset.keys.length};

constexpr Word VOCAB[VOCAB_KEYS] = {
${words.join('\n')}
};

// Keyword reported by the listening model -> vocabulary key (0-based) it highlights.
// Only vocabulary keys appear here; the generator rejects keywords on core keys.
struct KeywordMap {
  const char* word;
  uint8_t key;
};

constexpr KeywordMap KEYWORDS[] = {
${kw.join('\n')}
};
constexpr size_t NUM_KEYWORDS = sizeof(KEYWORDS) / sizeof(KEYWORDS[0]);

static_assert(CORE_KEYS == 4, "the core row is Yes, No, Help, Stop");
`;
}

function renderJson({ keyset, packs }) {
  return JSON.stringify({ generated: 'tools/vocab.mjs', keyset, packs: packs.map((p) => p.pack) }, null, 2) + '\n';
}

const [cmd = 'gen', ...args] = process.argv.slice(2);

if (cmd === 'validate') {
  const keyset = readJson(join(PACK_DIR, 'keys.json'));
  let bad = 0;
  for (const f of args) {
    let r;
    try {
      r = validatePack(readJson(f), keyset);
    } catch (e) {
      r = { errors: [`not valid JSON: ${e.message}`], warnings: [] };
    }
    console.log(`${r.errors.length ? '✗' : '✓'} ${f}`);
    for (const e of r.errors) console.log(`  error: ${e}`);
    for (const w of r.warnings) console.log(`  warning: ${w}`);
    if (r.errors.length) bad++;
  }
  process.exit(bad ? 1 : 0);
}

const data = load();
const outputs = [
  [OUT_H, renderHeader(data)],
  [OUT_JSON, renderJson(data)],
];

if (cmd === 'gen') {
  for (const [file, text] of outputs) writeFileSync(file, text);
  console.log(`✓ wrote ${outputs.map(([f]) => f.slice(root.length + 1)).join(', ')}`);
} else if (cmd === 'check') {
  const stale = outputs.filter(([file, text]) => !existsSync(file) || readFileSync(file, 'utf8').replace(/\r\n/g, '\n') !== text);
  if (stale.length) {
    console.error(`✗ stale: ${stale.map(([f]) => f.slice(root.length + 1)).join(', ')}. Run: node tools/vocab.mjs gen`);
    process.exit(1);
  }
  console.log('✓ generated vocabulary files are up to date');
} else if (cmd === 'report') {
  for (const { pack, report } of data.packs) {
    const c = report.coverage;
    console.log(`${pack.code} ${pack.name}: transliteration ${c.transliteration}/${c.keys}, native script ${c.native}/${c.keys} (native-reviewed ${c.nativeReviewed}), keyword keys ${c.keywords}`);
    for (const w of report.warnings) console.log(`  warning: ${w}`);
  }
} else {
  console.error(`unknown command "${cmd}" (gen | check | report | validate <files>)`);
  process.exit(2);
}
